 1→import { Toaster as Sonner } from "@/components/ui/sonner";
 2→import { TooltipProvider } from "@/components/ui/tooltip";
 3→import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
 4→import { BrowserRouter, Routes, Route } from "react-router-dom";
 5→import { AuthProvider, useAuth } from "@/hooks/useAuth";
 6→import { useFeatureFlag } from "@/hooks/useFeatureFlags";
 7→import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
 8→import MaintenancePage from "@/components/MaintenancePage";
 9→import Index from "./pages/Index";
10→import Auth from "./pages/Auth";
11→import Admin from "./pages/Admin";
12→import Settings from "./pages/Settings";
13→import NotFound from "./pages/NotFound";
14→import PaymentCallback from "./pages/PaymentCallback";
15→import BookDemo from "./pages/BookDemo";
16→import RequestFeature from "./pages/RequestFeature";
17→import SeoHead from "@/components/SeoHead";
18→import LandingPage from "@/components/LandingPage";
19→import ChatWidget from "@/components/ChatWidget";
20→
21→const queryClient = new QueryClient();
22→
23→const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
24→  const { enabled } = useFeatureFlag("maintenance_mode");
25→  const { isAdmin, loading } = useAuth();
26→
27→  if (loading) return null;
28→  if (enabled && !isAdmin) return <MaintenancePage />;
29→  return <>{children}</>;
30→};
31→
32→const RootRoute = () => {
33→  const { user, loading } = useAuth();
34→  if (loading) return null;
35→  return user ? <Index /> : <LandingPage />;
36→};
37→
38→const App = () => (
39→  <QueryClientProvider client={queryClient}>
40→    <AuthProvider>
41→      <TooltipProvider>
42→        <Sonner />
43→        <BrowserRouter>
44→          <SeoHead />
45→          <MaintenanceGate>
46→            <Routes>
47→              <Route path="/auth" element={<Auth />} />
48→              <Route path="/" element={<RootRoute />} />
49→              <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
50→              <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
51→              <Route path="/book-demo" element={<BookDemo />} />
52→              <Route path="/request-feature" element={<RequestFeature />} />
53→              <Route path="/payment/callback" element={<PaymentCallback />} />
54→              <Route path="*" element={<NotFound />} />
55→            </Routes>
56→          </MaintenanceGate>
57→          <ChatWidget />
58→        </BrowserRouter>
59→      </TooltipProvider>
60→    </AuthProvider>
61→  </QueryClientProvider>
62→);
63→
64→export default App;
