  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  parsed_json?: any;
 48→}
 49→
 50→export interface ExistingResume {
 51→  id: string;
 52→  filename: string;
 53→  file_path: string | null;
 54→  candidate_name: string | null;
 55→  created_at: string;
 56→}
 57→
 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      toast.error("Failed to load jobs");
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      // Deduplicate by resume_id — keep highest scoring result per resume
158→      const deduped = new Map<string, Result>();
159→      for (const r of allMerged) {
160→        const existing = deduped.get(r.resume_id);
161→        if (!existing || r.overall_score > existing.overall_score) {
162→          deduped.set(r.resume_id, r);
163→        }
164→      }
165→      const merged = Array.from(deduped.values());
166→      merged.sort((a, b) => b.overall_score - a.overall_score);
167→      setResults(merged);
168→    } catch (err) {
169→      toast.error("Failed to load job data");
170→    }
171→  };
172→
173→  const handleNewJob = () => {
174→    setSelectedJobId(null);
175→    setResults([]);
176→    setExistingResumes([]);
177→  };
178→
179→  const handleJobCreated = (job: PastJob) => {
180→    setPastJobs((prev) => [job, ...prev]);
181→    setSelectedJobId(job.id);
182→    loadJobData(job.id);
183→  };
184→
185→  const handleRenameJob = (jobId: string, newTitle: string) => {
186→    setPastJobs((prev) =>
187→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
188→    );
189→  };
190→
191→  const handleDeleteJob = async (jobId: string) => {
192→    try {
193→      await supabase.from("resumes").delete().eq("job_id", jobId);
194→      await supabase.from("jobs").delete().eq("id", jobId);
195→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
196→      if (selectedJobId === jobId) handleNewJob();
197→      toast.success("Job deleted");
198→    } catch {
199→      toast.error("Failed to delete job");
200→    }
201→  };
202→
203→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
204→    setPastJobs((prev) =>
205→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
206→    );
207→  };
208→
209→  const requireAuth = useCallback(() => {
210→    if (!user) { setAuthOpen(true); return true; }
211→    return false;
212→  }, [user]);
213→
214→  return (
215→    <SidebarProvider className="h-svh overflow-hidden">
216→      <JobSidebar
217→        pastJobs={pastJobs}
218→        selectedJobId={selectedJobId}
219→        loadingPastJobs={loadingPastJobs}
220→        onSelectJob={loadJobData}
221→        onNewJob={handleNewJob}
222→        onRenameJob={handleRenameJob}
223→        onDeleteJob={handleDeleteJob}
224→        onAuthRequired={() => setAuthOpen(true)}
225→        isAuthenticated={!!user}
226→      />
227→
228→      <SidebarInset className="h-svh overflow-y-auto">
229→        <AppHeader />
230→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
231→          <SidebarTrigger />
232→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
233→        </div>
234→        <JobDetailView
235→          selectedJobId={selectedJobId}
236→          selectedJob={selectedJob}
237→          results={results}
238→          setResults={setResults}
239→          existingResumes={existingResumes}
240→          setExistingResumes={setExistingResumes}
241→          onJobCreated={handleJobCreated}
242→          onAuthRequired={() => setAuthOpen(true)}
243→          isAuthenticated={!!user}
244→          onJobUpdated={handleJobUpdated}
245→        />
246→      </SidebarInset>
247→
248→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
249→    </SidebarProvider>
250→  );
251→};
252→
253→export default Index;
254→

  1→import { useState, useCallback, useRef, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { usePlatformConfig } from "@/hooks/usePlatformConfig";
  4→import { supabase } from "@/integrations/supabase/client";
  5→import { Button } from "@/components/ui/button";
  6→import { Textarea } from "@/components/ui/textarea";
  7→import { Checkbox } from "@/components/ui/checkbox";
  8→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  9→import { Badge } from "@/components/ui/badge";
 10→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
 11→import { Progress } from "@/components/ui/progress";
 12→import {
 13→  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
 14→  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
 15→} from "@/components/ui/alert-dialog";
 16→import { toast } from "sonner";
 17→import {
 18→  Upload, Copy, Loader2, FileText,
 19→  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
 20→  Brain, ListChecks, BarChart2, ArrowRight, Sparkles, Clock, Users, Star, Mail, Zap,
 21→  Archive, ArchiveRestore, FolderOpen, Wand2, Pencil
 22→} from "lucide-react";
 23→import { exportToCSV } from "@/lib/csvExport";
 24→import CandidateRow from "@/components/CandidateRow";
 25→import JDRewriteDialog from "@/components/JDRewriteDialog";
 26→import ScoreSummaryCards from "@/components/ScoreSummaryCards";
 27→import ConfidenceReport from "@/components/ConfidenceReport";
 28→import type { PastJob, Result, ExistingResume } from "@/pages/Index";
 29→import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
 30→
 31→interface JobDetailViewProps {
 32→  selectedJobId: string | null;
 33→  selectedJob: PastJob | null;
 34→  results: Result[];
 35→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
 36→  existingResumes: ExistingResume[];
 37→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
 38→  onJobCreated: (job: PastJob) => void;
 39→  onAuthRequired: () => void;
 40→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
 41→  isAuthenticated?: boolean;
 42→}
 43→
 44→interface UploadedFile {
 45→  file: File;
 46→  name: string;
 47→}
 48→
 49→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 50→
 51→const JobDetailView = ({
 52→  selectedJobId,
 53→  selectedJob,
 54→  results,
 55→  setResults,
 56→  existingResumes,
 57→  setExistingResumes,
 58→  onJobCreated,
 59→  onAuthRequired,
 60→  onJobUpdated,
 61→  isAuthenticated = true,
 62→}: JobDetailViewProps) => {
 63→  const { user, profile, refreshProfile } = useAuth();
 64→  const { data: config } = usePlatformConfig();
 65→
 66→  const [jobDescription, setJobDescription] = useState("");
 67→  const [files, setFiles] = useState<UploadedFile[]>([]);
 68→  const [ranking, setRanking] = useState(false);
 69→  const [rankingProgress, setRankingProgress] = useState(0);
 70→  const [scoredCount, setScoredCount] = useState(0);
 71→  const [totalToScore, setTotalToScore] = useState(0);
 72→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
 73→  const [dragOver, setDragOver] = useState(false);
 74→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
 75→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
 76→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
 77→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
 78→  const [deleting, setDeleting] = useState(false);
 79→  const [analyzingJd, setAnalyzingJd] = useState(false);
 80→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
 81→  const [showArchived, setShowArchived] = useState(false);
 82→  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
 83→  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
 84→  const [stuckJobDetected, setStuckJobDetected] = useState(false);
 85→  const [retrying, setRetrying] = useState(false);
 86→  const [editingJd, setEditingJd] = useState(false);
 87→  const [editedJdText, setEditedJdText] = useState("");
 88→  const [confirmEditJdOpen, setConfirmEditJdOpen] = useState(false);
 89→
 90→  const resultsRef = useRef<HTMLDivElement>(null);
 91→  const rankingFilesRef = useRef<Set<string>>(new Set());
 92→  const activeJobRef = useRef<string | null>(selectedJobId);
 93→  const maxResumes = config?.max_resumes_per_job ?? 10;
 94→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
 95→
 96→  const isNewJobMode = selectedJobId === null;
 97→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
 98→
 99→  // Hiring Stage Tracker
100→  const { data: stages } = useStages(selectedJobId);
101→  const updateStageMutation = useUpdateStage();
102→  const stageSummary = useStageSummary(selectedJobId);
103→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
104→
105→  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
106→    if (!selectedJobId) return;
107→    const current = stageMap.get(resumeId);
108→    updateStageMutation.mutate({
109→      resumeId,
110→      jobId: selectedJobId,
111→      newStage,
112→      currentStage: current?.stage,
113→    });
114→  };
115→
116→  const formatCandidateName = (filename: string) => {
117→    const name = filename.replace(/\.\w+$/, "");
118→    if (UUID_REGEX.test(name)) return `Resume ${name.slice(0, 6).toUpperCase()}`;
119→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
120→  };
121→
122→  // Merge unranked resumes
123→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
124→  const pendingResumes: Result[] = existingResumes
125→    .filter((r) => !resultResumeIds.has(r.id))
126→    .map((r) => ({
127→      id: `pending-${r.id}`,
128→      resume_id: r.id,
129→      overall_score: 0,
130→      missing_skills: [], summary: null, interview_questions: null,
131→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
132→      pending: true,
133→    }));
134→  const allResults = [...results, ...pendingResumes];
135→
136→  // Selection helpers
137→  const toggleSelectResume = (resumeId: string) => {
138→    setSelectedResumes((prev) => {
139→      const next = new Set(prev);
140→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
141→      return next;
142→    });
143→  };
144→  const toggleSelectAll = () => {
145→    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
146→    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
147→  };
