111→  );
112→  const resumeTools = (p.tools || []).map((t: string) => t.toLowerCase());
113→  const domains = p.domain_experience ? [p.domain_experience.toLowerCase()] : [];
114→  const roleTitles = (p.roles_with_dates || []).map((r: any) => (r.title || r.role || '').toLowerCase());
115→  return [...resumeSkills, ...resumeTools, ...domains, ...roleTitles].filter(Boolean);
