133→function mergeSkillSynonyms(adminSynonyms: Record<string, string[]>) {
134→  const merged = { ...SKILL_SYNONYMS };
135→  for (const [canonical, syns] of Object.entries(adminSynonyms)) {
136→    const key = canonical.toLowerCase().trim();
137→    merged[key] = [...new Set([...(merged[key] || []), ...syns.map(s => s.toLowerCase().trim())])];
138→  }
139→  // Rebuild the lookup map
140→  for (const [canonical, syns] of Object.entries(merged)) {
141→    synonymToCanonical.set(canonical, canonical);
142→    for (const syn of syns) synonymToCanonical.set(syn, canonical);
143→  }
144→  return merged;
145→}
