228→function extractRequiredYears(experienceReq: string): number {
229→  if (!experienceReq) return 0;
230→  const match = experienceReq.match(/(\d+)\+?\s*(?:years?|yrs?)/i);
231→  return match ? parseInt(match[1]) : 0;
232→}
233→
234→function scoreExperienceBand(years: number, bands: ExperienceBand[]): number {
235→  for (const band of bands) {
236→    if (years >= band.min_years && years < band.max_years) return band.score;
237→  }
238→  // If beyond all bands, return max score
239→  return bands.length > 0 ? bands[bands.length - 1].score : 50;
240→}
