242→function scoreEducation(education: any[], levels: EducationLevel[]): { score: number; highestDegree: string } {
243→  if (!Array.isArray(education) || education.length === 0) {
244→    return { score: 0, highestDegree: "none" };
245→  }
246→
247→  let bestScore = 0;
248→  let bestLevel = "unknown";
249→
250→  for (const edu of education) {
251→    const degree = String(edu.degree || edu.qualification || edu.level || "").toLowerCase().trim();
252→    if (!degree) continue;
253→
254→    for (const level of levels) {
255→      for (const alias of level.aliases) {
256→        if (degree.includes(alias.toLowerCase())) {
257→          if (level.score > bestScore) {
258→            bestScore = level.score;
259→            bestLevel = level.level;
260→          }
261→          break;
262→        }
263→      }
264→    }
265→  }
266→
267→  return { score: bestScore, highestDegree: bestLevel };
268→}
