272→  jdAnalysis: any,
273→  cfg: {
274→    experience_bands: ExperienceBand[];
275→    education_levels: EducationLevel[];
276→    rule_dimension_weights: Record<string, number>;
277→    must_have_penalty_per_missing: number;
278→    hard_fit_cap: number;
279→    algorithm_version: number;
280→  },
281→) {
282→  const p = parsedJson || {};
283→  const allResumeTerms = extractResumeTerms(parsedJson);
284→
285→  // ── Skill Match ──
286→  const jdSkills = [
287→    ...(jdAnalysis.critical_must_haves || []),
288→    ...(jdAnalysis.preferred_must_haves || []),
289→    ...(jdAnalysis.nice_to_have || []),
290→  ];
291→  const matchedSkills: string[] = [];
292→  const missingSkills: string[] = [];
293→  for (const skill of jdSkills) {
294→    if (fuzzyMatch(skill, allResumeTerms)) matchedSkills.push(skill);
295→    else missingSkills.push(skill);
296→  }
297→  const skillScore = jdSkills.length > 0 ? Math.round((matchedSkills.length / jdSkills.length) * 100) : 50;
298→
299→  // ── Tool Match ──
300→  const jdTools = jdAnalysis.tools || [];
301→  const matchedTools: string[] = [];
302→  const missingTools: string[] = [];
303→  for (const tool of jdTools) {
304→    if (fuzzyMatch(tool, allResumeTerms)) matchedTools.push(tool);
305→    else missingTools.push(tool);
306→  }
307→  const toolScore = jdTools.length > 0 ? Math.round((matchedTools.length / jdTools.length) * 100) : 50;
308→
309→  // ── Experience Fit ──
310→  const rolesWithDates = p.roles_with_dates || [];
311→  const totalYears = extractTotalYears(rolesWithDates);
312→  const requiredYears = extractRequiredYears(jdAnalysis.experience_requirements || "");
313→  let experienceScore = scoreExperienceBand(totalYears, cfg.experience_bands);
314→  if (requiredYears > 0 && totalYears >= requiredYears) {
315→    experienceScore = Math.min(100, experienceScore + 10);
316→  }
317→
318→  // ── Education Fit ──
319→  const education = p.education || [];
320→  const eduResult = scoreEducation(education, cfg.education_levels);
321→  const educationScore = eduResult.score;
322→
323→  // ── Must-Have Coverage ──
324→  const criticalMustHaves = jdAnalysis.critical_must_haves || [];
325→  const matchedMustHaves: string[] = [];
326→  const missingMustHaves: string[] = [];
327→  for (const mh of criticalMustHaves) {
328→    if (fuzzyMatch(mh, allResumeTerms)) matchedMustHaves.push(mh);
329→    else missingMustHaves.push(mh);
330→  }
331→  const mustHaveScore = criticalMustHaves.length > 0
332→    ? Math.round((matchedMustHaves.length / criticalMustHaves.length) * 100) : 100;
333→
334→  // ── Overall Score ──
335→  const weights = cfg.rule_dimension_weights;
336→  let overallScore =
337→    skillScore * (weights.skill_match || 0.30) +
338→    experienceScore * (weights.experience_fit || 0.25) +
339→    toolScore * (weights.tool_match || 0.20) +
340→    educationScore * (weights.education_fit || 0.15) +
341→    mustHaveScore * (weights.must_have_coverage || 0.10);
342→
343→  // Apply must-have penalty
344→  overallScore -= missingMustHaves.length * cfg.must_have_penalty_per_missing;
345→  overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
346→
347→  // Hard fit check
348→  const hardFit = missingMustHaves.length === 0;
349→  if (!hardFit) {
350→    overallScore = Math.min(overallScore, cfg.hard_fit_cap);
351→  }
352→
353→  // ── Build strengths & gaps ──
354→  const dimensionScores = [
355→    { name: "Skill Match", score: skillScore },
356→    { name: "Experience", score: experienceScore },
357→    { name: "Tools", score: toolScore },
358→    { name: "Education", score: educationScore },
359→    { name: "Must-Haves", score: mustHaveScore },
360→  ];
361→  dimensionScores.sort((a, b) => b.score - a.score);
362→  const strengths = dimensionScores.filter(d => d.score >= 60).map(d => `${d.name}: ${d.score}%`);
363→  const gaps = dimensionScores.filter(d => d.score < 50).map(d => `${d.name}: ${d.score}%`);
364→
365→  // Add matched skills to strengths
366→  if (matchedMustHaves.length > 0) {
367→    strengths.push(`Matched must-haves: ${matchedMustHaves.join(", ")}`);
368→  }
369→  if (missingMustHaves.length > 0) {
370→    gaps.push(`Missing must-haves: ${missingMustHaves.join(", ")}`);
371→  }
372→
373→  return {
374→    scoring_version: `rule-v1-algo${cfg.algorithm_version}`,
375→    overall_score: overallScore,
376→    hard_fit: hardFit,
377→    confidence: 100,
378→    skill_score: skillScore,
379→    experience_score: experienceScore,
380→    education_score: educationScore,
381→    category_scores_json: {
