383→      experience_fit: { score: experienceScore, years_found: totalYears, years_required: requiredYears },
384→      tool_match: { score: toolScore, matched: matchedTools, missing: missingTools },
385→      education_fit: { score: educationScore, highest_degree: eduResult.highestDegree },
386→      must_have_coverage: { score: mustHaveScore, matched: matchedMustHaves, missing: missingMustHaves },
387→    },
388→    matched_must_haves: matchedMustHaves,
389→    missing_must_haves: missingMustHaves,
390→    missing_skills: [...missingMustHaves, ...missingTools],
391→    strengths_json: strengths,
392→    gaps_json: gaps,
393→    interview_questions: [],
394→    explanation_json: {
