450→- category_scores: object where each key is a dimension key, value is {score: 0-100, evidence: [{snippet: string, section: string}], notes: string}
451→- strengths: string[] (all notable strengths for this specific role — include as many as the resume supports, no fixed limit)
452→- gaps: string[] (all notable gaps/weaknesses for this specific role — include as many as are relevant, no fixed limit)
453→- interview_questions: string[] (${cfg.num_interview_questions} questions targeting gaps)
454→- explanation: {summary: string, why_ranked_here: string, key_tradeoffs: string}
455→- confidence: number 0-100 (based on resume text quality and evidence density)
456→
457→Return ONLY valid JSON. No markdown.`;
458→
459→  const systemPrompt = customSystemPrompt
460→    ? applyPromptTemplate(customSystemPrompt, {
461→        criticalMustHaves: criticalMustHaves || "None specified",
462→        preferredMustHaves: preferredMustHaves || "None specified",
463→        dimensionInstructions,
464→        "cfg.num_interview_questions": String(cfg.num_interview_questions),
465→        num_interview_questions: String(cfg.num_interview_questions),
466→      })
467→    : hardcodedDeepPrompt;
468→
469→  const maxChars = cfg.max_resume_chars;
470→  const resumeContent = parsedJson
471→    ? `STRUCTURED RESUME DATA:\n${JSON.stringify(parsedJson).slice(0, maxChars)}\n\nRAW RESUME TEXT:\n${resumeText.slice(0, maxChars / 2)}`
472→    : `RESUME TEXT:\n${resumeText.slice(0, maxChars)}`;
473→
474→  const response = await fetch("https://api.openai.com/v1/chat/completions", {
475→    method: "POST",
476→    headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, "Content-Type": "application/json" },
477→    body: JSON.stringify({
478→      model: cfg.model,
479→      messages: [
480→        { role: "system", content: systemPrompt },
481→        { role: "user", content: `JOB DESCRIPTION:\n${jdText.slice(0, maxChars)}\n\n${resumeContent}` },
482→      ],
483→      response_format: { type: "json_object" },
484→      temperature: cfg.temperature,
485→    }),
486→  });
487→
488→  if (!response.ok) {
489→    const errBody = await response.text();
490→    throw new Error(`OpenAI score error ${response.status}: ${errBody.slice(0, 200)}`);
491→  }
492→
493→  const data = await response.json();
494→  const content = data.choices?.[0]?.message?.content;
495→  if (!content) throw new Error("OpenAI returned empty deep score response");
496→  return JSON.parse(content);
497→}
