499→// ── Process a single resume: parse + score ──────────────────
500→async function processResume(
501→  supabase: any,
502→  resumeId: string,
503→  jobId: string,
504→  userId: string,
505→  cfg: any,
506→  deepScoringPrompt: string | null,
507→  job: any,
508→  jdAnalysis: any,
509→  dynamicWeights: any,
510→  jdEmbedding: any,
511→  dimensions: any[],
512→) {
513→  // Step 1: Call parse-resume to extract text + structured data
514→  console.log(`Parsing resume ${resumeId}...`);
515→  try {
516→    const { data: parseResult, error: parseError } = await supabase.functions.invoke("parse-resume", {
517→      body: { resume_id: resumeId, job_id: jobId },
518→    });
519→    if (parseError) {
520→      console.error(`parse-resume invocation error for ${resumeId}:`, parseError);
521→    } else {
522→      console.log(`Resume ${resumeId} parsed: method=${parseResult?.extraction_method}, chars=${parseResult?.text_length}, sufficient=${parseResult?.sufficient}`);
523→    }
524→  } catch (err) {
525→    console.error(`parse-resume call failed for ${resumeId}:`, err);
526→    await logSystemError({ function_name: "rank-resumes", error_type: "PARSE_INVOKE", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
527→  }
528→
529→  // Step 2: Re-fetch resume after parsing
530→  const { data: resume } = await supabase.from("resumes").select("*").eq("id", resumeId).single();
531→  if (!resume) {
532→    console.error(`Resume ${resumeId} not found after parsing`);
533→    return false;
534→  }
535→
536→  const rawText = resume.parsed_text || "";
537→  const parsedJson = resume.parsed_json;
538→
539→  // Step 3: Check if we have enough content to score
540→  const hasUsefulParsedJson = parsedJson && (
541→    (Array.isArray(parsedJson.skills_with_evidence) && parsedJson.skills_with_evidence.length > 0) ||
542→    (Array.isArray(parsedJson.roles_with_dates) && parsedJson.roles_with_dates.length > 0) ||
543→    (Array.isArray(parsedJson.education) && parsedJson.education.length > 0)
544→  );
545→  if (rawText.trim().length < 50 && !hasUsefulParsedJson) {
546→    console.warn(`Resume ${resumeId}: insufficient content after parsing, inserting zero score`);
547→    const summaryMsg = resume.status === "failed"
548→      ? "Could not extract text from this file. It may be image-based or have unsupported formatting. Please re-upload a text-based PDF or DOCX file."
549→      : "Resume content too short to evaluate. Please re-upload a valid PDF/DOCX.";
550→    const resultData = {
551→      resume_id: resumeId, job_id: jobId, scoring_version: "insufficient",
552→      overall_score: 0, hard_fit: false, confidence: 0,
553→      category_scores_json: {}, strengths_json: [], gaps_json: [],
554→      interview_questions: [], explanation_json: { extraction_failed: true },
555→      matched_must_haves: [], missing_must_haves: [], missing_skills: [],
556→      summary: summaryMsg,
557→      skill_score: null, experience_score: null, education_score: null,
558→    };
559→    const { data: existing } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
560→    if (existing) await supabase.from("results").update(resultData as any).eq("id", existing.id);
561→    else await supabase.from("results").insert(resultData as any);
562→    return false;
563→  }
564→
565→  // Step 4: Score — rule-based or GPT
566→  if (cfg.scoring_mode === "rule_based") {
567→    try {
568→      console.log(`Rule-based scoring for resume ${resumeId}...`);
569→      const ruleResult = ruleBasedScoreResume(parsedJson, jdAnalysis, cfg);
570→
571→      // Update candidate name from parsed data if available
572→      const parsedName = parsedJson?.candidate_name || parsedJson?.name;
573→      if (parsedName && parsedName !== "Unknown Candidate") {
574→        await supabase.from("resumes").update({ candidate_name: parsedName, status: "done" }).eq("id", resumeId);
575→      } else {
576→        await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
577→      }
578→
579→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
580→      const resultData = { resume_id: resumeId, job_id: jobId, ...ruleResult };
581→
582→      if (existingResult) {
583→        await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
584→      } else {
585→        await supabase.from("results").insert(resultData as any);
586→      }
587→      console.log(`Resume ${resumeId} rule-scored: overall=${ruleResult.overall_score}, hardFit=${ruleResult.hard_fit}`);
588→      return true;
589→    } catch (err) {
590→      console.error(`Rule-based scoring failed for ${resumeId}:`, err);
591→      await logSystemError({ function_name: "rank-resumes", error_type: "RULE_SCORING", severity: "error", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
592→      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
593→      return false;
594→    }
595→  }
596→
597→  // Step 5: Deep score with OpenAI (GPT mode)
598→  try {
599→    const resumeText = rawText || JSON.stringify(parsedJson || {});
600→    const deepResult = await deepScoreResume(
601→      job.job_description, resumeText, parsedJson,
602→      jdAnalysis, dimensions, cfg, deepScoringPrompt
603→    );
604→
605→    let overallScore = 0;
606→    const categoryScores = deepResult.category_scores || {};
607→
608→    const normalizeKey = (k: string) => k.toLowerCase().replace(/[\s_-]+/g, "_").trim();
609→    const scoreKeyMap = new Map<string, any>();
610→    for (const [k, v] of Object.entries(categoryScores)) {
611→      scoreKeyMap.set(normalizeKey(k), v);
612→    }
613→
614→    for (const dim of dimensions) {
615→      const weight = dynamicWeights[dim.key] ?? 0;
616→      const scoreEntry = categoryScores[dim.key] || scoreKeyMap.get(normalizeKey(dim.key));
617→      overallScore += (scoreEntry?.score ?? 0) * weight;
618→    }
619→
620→    if (overallScore === 0 && Object.keys(categoryScores).length > 0) {
621→      const allScores = Object.values(categoryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
622→      if (allScores.length > 0) overallScore = allScores.reduce((a: number, b: number) => a + b, 0) / allScores.length;
623→    }
624→
625→    overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
626→
627→    // All-zero retry
628→    const allZero = Object.values(categoryScores).every((v: any) => (v?.score ?? 0) === 0);
629→    if (allZero && resumeText.length > 200 && (deepResult.confidence ?? 0) === 0) {
630→      console.warn(`Resume ${resumeId}: all scores=0, retrying once...`);
631→      try {
632→        const retryResult = await deepScoreResume(
633→          job.job_description, resumeText, parsedJson,
634→          jdAnalysis, dimensions, cfg, deepScoringPrompt
635→        );
636→        const retryScores = retryResult.category_scores || {};
637→        const retryAllZero = Object.values(retryScores).every((v: any) => (v?.score ?? 0) === 0);
638→        if (!retryAllZero) {
639→          Object.assign(deepResult, retryResult);
640→          Object.assign(categoryScores, retryScores);
641→          overallScore = 0;
642→          const retryKeyMap = new Map<string, any>();
643→          for (const [k, v] of Object.entries(retryScores)) retryKeyMap.set(normalizeKey(k), v);
644→          for (const dim of dimensions) {
645→            const weight = dynamicWeights[dim.key] ?? 0;
646→            const scoreEntry = retryScores[dim.key] || retryKeyMap.get(normalizeKey(dim.key));
647→            overallScore += (scoreEntry?.score ?? 0) * weight;
648→          }
649→          if (overallScore === 0 && Object.keys(retryScores).length > 0) {
650→            const rs = Object.values(retryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
651→            if (rs.length > 0) overallScore = rs.reduce((a: number, b: number) => a + b, 0) / rs.length;
652→          }
653→          overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
654→        }
655→      } catch (retryErr) {
656→        console.error(`Retry scoring failed for ${resumeId}:`, retryErr);
657→      }
658→    }
659→
660→    let hardFit = deepResult.hard_fit !== false;
661→    const missingCritical = deepResult.missing_critical_must_haves || [];
662→    const hardFitCap = cfg.hard_fit_cap ?? 49;
663→    if (missingCritical.length > 0) {
664→      hardFit = false;
665→      overallScore = Math.min(overallScore, hardFitCap);
666→    }
667→
668→    // Update name if scoring found a better one
669→    const bestName = resume.candidate_name;
670→    if (deepResult.candidate_name && deepResult.candidate_name !== "Unknown Candidate") {
671→      await supabase.from("resumes").update({ candidate_name: deepResult.candidate_name, status: "done" }).eq("id", resumeId);
672→    } else {
673→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
674→    }
675→
676→    const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
677→    const resultData = {
678→      resume_id: resumeId, job_id: jobId, scoring_version: `v7-algo${cfg.algorithm_version ?? 1}`,
679→      overall_score: overallScore, hard_fit: hardFit,
680→      confidence: deepResult.confidence ?? 0,
681→      category_scores_json: categoryScores,
682→      strengths_json: deepResult.strengths || [],
683→      gaps_json: deepResult.gaps || [],
684→      interview_questions: deepResult.interview_questions || [],
685→      explanation_json: {
686→        ...(deepResult.explanation || {}),
687→        matched_preferred: deepResult.matched_preferred_must_haves || [],
688→        missing_preferred: deepResult.missing_preferred_must_haves || [],
689→      },
690→      matched_must_haves: deepResult.matched_critical_must_haves || [],
691→      missing_must_haves: missingCritical,
692→      missing_skills: missingCritical,
693→      summary: deepResult.explanation?.summary || "",
694→      skill_score: null, experience_score: null, education_score: null,
695→    };
696→
697→    if (existingResult) {
698→      await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
699→    } else {
700→      await supabase.from("results").insert(resultData as any);
701→    }
702→    console.log(`Resume ${resumeId} scored: overall=${overallScore}, hardFit=${hardFit}`);
703→    return true;
704→
705→  } catch (err) {
706→    console.error(`Deep scoring failed for ${resumeId}, falling back to heuristic:`, err);
707→    await logSystemError({ function_name: "rank-resumes", error_type: "GPT_SCORING", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
708→
709→    // Heuristic fallback
710→    try {
711→      const allResumeTerms = extractResumeTerms(parsedJson);
712→      const mustHaves = jdAnalysis.critical_must_haves || [];
713→      const jdTools = jdAnalysis.tools || [];
714→      const totalKeywords = mustHaves.length + jdTools.length;
715→      let matchedCount = 0;
716→      const matchedSkills: string[] = [];
717→      const missingSkills: string[] = [];
718→
719→      for (const mh of mustHaves) {
720→        if (fuzzyMatch(mh, allResumeTerms)) { matchedCount++; matchedSkills.push(mh); }
721→        else { missingSkills.push(mh); }
722→      }
723→      for (const tool of jdTools) {
724→        if (fuzzyMatch(tool, allResumeTerms)) { matchedCount++; matchedSkills.push(tool); }
725→      }
726→
727→      const keywordScore = totalKeywords > 0 ? (matchedCount / totalKeywords) * 100 : 30;
728→      let similarity = 0.3;
729→      if (jdEmbedding) {
730→        const { data: simResult } = await supabase.rpc("match_resumes_by_embedding", {
731→          query_embedding: jdEmbedding, match_job_id: jobId, match_count: 1,
732→        });
733→        const match = (simResult || []).find((s: any) => s.id === resumeId);
734→        if (match) similarity = match.similarity;
735→      }
736→      let heuristicScore = Math.round(similarity * 100 * 0.6 + keywordScore * 0.4);
737→      const hFit = missingSkills.length === 0;
738→      if (!hFit) heuristicScore = Math.min(heuristicScore, 49);
739→      heuristicScore = Math.max(0, Math.min(100, heuristicScore));
740→
741→      const summary = `AI scoring unavailable — ranked by keyword match (${matchedCount}/${totalKeywords}).`;
742→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
743→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
744→      const resultData = {
745→        resume_id: resumeId, job_id: jobId, scoring_version: "heuristic",
746→        overall_score: heuristicScore, hard_fit: hFit,
747→        confidence: Math.min(Math.round((matchedCount / Math.max(totalKeywords, 1)) * 40), 40),
748→        category_scores_json: {}, strengths_json: matchedSkills.slice(0, 5),
749→        gaps_json: missingSkills.slice(0, 5), interview_questions: [],
750→        explanation_json: { summary }, matched_must_haves: matchedSkills,
751→        missing_must_haves: missingSkills, missing_skills: missingSkills, summary,
752→        skill_score: null, experience_score: null, education_score: null,
753→      };
754→      if (existingResult) await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
755→      else await supabase.from("results").insert(resultData as any);
756→      return true;
757→    } catch (fallbackErr) {
758→      console.error(`Heuristic fallback also failed for ${resumeId}:`, fallbackErr);
759→      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
760→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
761→      if (!existingResult) {
762→        await supabase.from("results").insert({
763→          resume_id: resumeId, job_id: jobId, overall_score: 0, hard_fit: false,
764→          confidence: 0, category_scores_json: {}, strengths_json: [], gaps_json: [],
765→          summary: `Scoring failed: ${err instanceof Error ? err.message : "Unknown error"}`,
766→        } as any);
767→      }
768→      return false;
769→    }
770→  }
771→}
